/* @autogenerated */
package net.civeira.phylax.feature.oauth.tokensecurity.application;

import java.time.Duration;
import java.time.Instant;
import java.util.UUID;

import lombok.Builder;
import lombok.Data;

/**
 * Family of rotated refresh tokens that comes from one grant.
 *
 * Every refresh of the family carries the same {@code fid} and absolute expiration {@code fexp}, so
 * rotation never extends the grant. {@code sessionBound} marks families issued from an interactive
 * session: their refresh tokens only work while that session is alive.
 */
@Data
@Builder
public class RefreshFamily {
  /**
   * Family identifier (UUID); revoking it revokes every refresh of the family.
   */
  private final String fid;
  /**
   * Absolute expiration of the family.
   */
  private final Instant fexp;
  /**
   * Whether the family belongs to an interactive session.
   */
  private final boolean sessionBound;

  /**
   * Starts a new family.
   *
   * @param maxLifetime absolute lifetime of the family
   * @param sessionBound whether it belongs to an interactive session
   * @return new family
   */
  public static RefreshFamily start(Duration maxLifetime, boolean sessionBound) {
    return RefreshFamily.builder().fid(UUID.randomUUID().toString())
        .fexp(Instant.now().plus(maxLifetime)).sessionBound(sessionBound).build();
  }

  /**
   * Expiration of a refresh issued now: its own TTL, never after the family.
   *
   * @param ttl refresh TTL
   * @return expiration
   */
  public Instant expiration(Duration ttl) {
    Instant own = Instant.now().plus(ttl);
    return own.isAfter(fexp) ? fexp : own;
  }
}
